The error came from the executor trying to serialize tuple-keyed dictionaries. I’m rerunning the exact three-slot transition with list-based states, preserving empty platform positions so the final balls are handled correctly.
```python
marker = search_result
states_list = [((1, 2, 3), 4, 1.0)]
win_exact = [0.0] * 101
released_exact = [0.0] * 101

for step in range(500):
    next_list = []
    for plat, nxt, mass in states_list:
        for pos in range(3):
            q = mass / 3.0
            p1, p2, p3 = plat
            if pos == 0:
                if p1 is not None:
                    win_exact[p1] += q
                updated = [p2, p3, None]
            elif pos == 1:
                if p1 is not None:
                    released_exact[p1] += q
                if p3 is not None:
                    updated = [p3, None, None]
                else:
                    updated = [None, None, None]
            else:
                if p1 is not None:
                    released_exact[p1] += q
                updated = [p2, None, None]

            next_nxt = nxt
            for j in range(3):
                if updated[j] is None and next_nxt <= 100:
                    updated[j] = next_nxt
                    next_nxt += 1

            if any(x is not None for x in updated):
                next_list.append((tuple(updated), next_nxt, q))

    merged = {}
    for plat, nxt, mass in next_list:
        found = False
        for i in range(len(merged)):
            if merged[i][0] == plat and merged[i][1] == nxt:
                merged[i] = (plat, nxt, merged[i][2] + mass)
                found = True
                break
        if not found:
            merged[len(merged)] = (plat, nxt, mass)
    states_list = list(merged.values())
    if not states_list:
        break

ranking_exact = sorted(((win_exact[i], i) for i in range(1, 101)), reverse=True)
print(f"best_ball={ranking_exact[0][1]}; probability={ranking_exact[0][0]:.12f}; top10={ranking_exact[:10]}; total_ejection_probability={sum(win_exact):.12f}; marker_used={len(marker)}")
